function sanitizeTranscribedText(text) {
  if (typeof text !== 'string') return '';

  let cleaned = text.trim().replace(/\s+/g, ' ');

  // Normalize common spoken email formats only when
  // a recognizable email-like pattern is present.
  const emailPattern =
    /([a-zA-Z0-9._%+-]+)\s*(?:@|\bat\b|\(at\)|\[at\])\s*([a-zA-Z0-9-]+(?:\s*(?:\.|\bdot\b|\(dot\)|\[dot\])\s*[a-zA-Z0-9-]+)+)/gi;

  cleaned = cleaned.replace(emailPattern, (_match, username, domain) => {
    const normalizedDomain = domain
      .replace(/\s*(?:\bdot\b|\(dot\)|\[dot\]|\.)\s*/gi, '.')
      .replace(/\s+/g, '');

    return `${username}@${normalizedDomain}`;
  });

  return cleaned;
}

const items = $input.all();

for (const item of items) {
  const rawTranscript = item.json.text ?? '';

  item.json.sanitized_transcript =
    sanitizeTranscribedText(rawTranscript);
}

return items;

const items = $input.all();

for (const item of items) {
  if (!item.binary) {
    throw new Error("No audio file received.");
  }

  if (item.binary.data && !item.binary.audio) {
    item.binary.audio = item.binary.data;
  }

  if (!item.binary.audio) {
    throw new Error("Missing audio binary field.");
  }
}

return items;
